import sys
def longest_common_prefix(strs):
    if not strs: return ""
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix: return ""
    return prefix

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if data:
        n = int(data[0])
        strs = data[1:n+1]
        print(longest_common_prefix(strs))

